def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate each 4-column, 5-bordered open-top structure.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            minr = min(rr for rr, _ in comp)
            maxr = max(rr for rr, _ in comp)
            minc = min(cc for _, cc in comp)
            maxc = max(cc for _, cc in comp)
            # The opening is the zero in the top row of the 4-wide frame.
            openings = [cc for cc in range(minc, maxc + 1) if grid[minr][cc] == 0]
            if len(openings) != 1:
                continue
            gap = openings[0]
            out[minr][gap] = 2
            if minr > 0:
                for cc in range(gap + 1):
                    if out[minr - 1][cc] == 0:
                        out[minr - 1][cc] = 2
            for rr in range(minr + 1, maxr):
                for cc in range(minc + 1, maxc):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 2
    return out
